import { NativeStackScreenProps } from '@react-navigation/native-stack';
import React, { useState } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Button } from '../../components/Button';
import { RootStackParamList } from '../../navigation';
import { colors, radius, spacing, typography } from '../../theme/theme';

type Props = NativeStackScreenProps<RootStackParamList, 'ClientSignupSuccess'>;

/**
 * Final signup screen — shows the permanent 5-digit code generated by the
 * backend. The client must save it; there is no SMS / email / recovery.
 */
export const ClientSignupSuccessScreen: React.FC<Props> = ({ navigation, route }) => {
  const { code, pseudonym, email } = route.params;
  const [copied, setCopied] = useState(false);

  const copy = async () => {
    try {
      if (typeof navigator !== 'undefined' && navigator.clipboard) {
        await navigator.clipboard.writeText(code);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      }
    } catch {
      /* ignore */
    }
  };

  return (
    <SafeAreaView style={styles.safe} edges={['top', 'left', 'right', 'bottom']}>
      <View style={styles.topBar}>
        <Pressable
          onPress={() => navigation.reset({ index: 0, routes: [{ name: 'ClientQR' }] })}
          hitSlop={12}
          accessibilityRole="button"
          accessibilityLabel="Retour"
        >
          <Text style={styles.backArrow}>‹</Text>
        </Pressable>
      </View>
      <View style={styles.content}>
        <View style={styles.logoCircle}>
          <Text style={styles.logoEmoji}>🎉</Text>
        </View>
        <Text style={styles.title}>Bienvenue {pseudonym} !</Text>
        <Text style={styles.sub}>Ton compte est créé. Voici ton code de connexion :</Text>

        <Pressable onPress={copy} style={styles.codeBox} hitSlop={8}>
          <Text style={styles.codeLabel}>TON CODE</Text>
          <Text style={styles.code}>{code}</Text>
          <Text style={styles.copyHint}>{copied ? '✓ Copié' : 'Toucher pour copier'}</Text>
        </Pressable>

        {email ? (
          <View style={styles.info}>
            <Text style={styles.infoTitle}>📧 Code envoyé par email</Text>
            <Text style={styles.infoBody}>
              On t'a aussi envoyé ton code à <Text style={{ fontWeight: '700' }}>{email}</Text>.
              Vérifie ta boîte (et tes spams).
            </Text>
          </View>
        ) : (
          <View style={styles.warning}>
            <Text style={styles.warnTitle}>⚠️ Note bien ce code</Text>
            <Text style={styles.warnBody}>
              C'est lui qui te servira à te reconnecter. Il n'est envoyé nulle part — si tu le
              perds, tu ne pourras plus accéder à ton compte.
            </Text>
          </View>
        )}
      </View>

      <View style={styles.footer}>
        <Button
          title="J'ai noté mon code"
          variant="primary"
          onPress={() => navigation.reset({ index: 0, routes: [{ name: 'ClientQR' }] })}
        />
      </View>
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg, paddingHorizontal: spacing.lg },
  topBar: { paddingTop: spacing.sm },
  backArrow: { fontSize: 30, lineHeight: 30, color: colors.text, fontWeight: '800' },
  content: { flex: 1, justifyContent: 'center', alignItems: 'center', gap: spacing.md },
  logoCircle: {
    width: 88,
    height: 88,
    borderRadius: 44,
    backgroundColor: colors.surface,
    alignItems: 'center',
    justifyContent: 'center',
  },
  logoEmoji: { fontSize: 44 },
  title: { ...typography.h1, color: colors.text, textAlign: 'center' },
  sub: { ...typography.body, color: colors.textMuted, textAlign: 'center' },
  codeBox: {
    marginTop: spacing.md,
    width: '100%',
    alignItems: 'center',
    backgroundColor: colors.surface,
    borderRadius: radius.md,
    paddingVertical: spacing.lg,
    paddingHorizontal: spacing.md,
    gap: spacing.sm,
  },
  codeLabel: {
    ...typography.small,
    color: colors.textMuted,
    fontWeight: '700',
    letterSpacing: 1,
  },
  code: {
    fontSize: 56,
    fontWeight: '800',
    letterSpacing: 14,
    color: colors.primary,
  },
  copyHint: { ...typography.small, color: colors.textMuted },
  warning: {
    marginTop: spacing.md,
    width: '100%',
    backgroundColor: '#FFF8E6',
    borderRadius: radius.md,
    padding: spacing.md,
    gap: 6,
  },
  warnTitle: { ...typography.body, color: '#7A5A00', fontWeight: '700' },
  warnBody: { ...typography.small, color: '#7A5A00', lineHeight: 18 },
  info: {
    marginTop: spacing.md,
    width: '100%',
    backgroundColor: '#EAF4FF',
    borderRadius: radius.md,
    padding: spacing.md,
    gap: 6,
  },
  infoTitle: { ...typography.body, color: '#0B4A8C', fontWeight: '700' },
  infoBody: { ...typography.small, color: '#0B4A8C', lineHeight: 18 },
  footer: { paddingBottom: spacing.lg },
});
